#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# 05_prepare_membrane.sh -- stage the 8TH3 nanobody/AT1R membrane system.
#
# Building a GPCR bilayer needs an orienting and packing tool; this suite
# supports two routes:
#
#  A) CHARMM-GUI Membrane Builder (RECOMMENDED) --------------------------
#     1. Upload  simulation/data/8TH3_complex.pdb  (generated by
#        fetch_and_split.py) to  https://charmm-gui.org/?doc=input/membrane
#        -> GROMACS input generator, POPC, 0.15 M NaCl, PBC.
#        (Optional but recommended: use their "PDB Reader" MODELLER step to
#         rebuild the unmodeled nanobody N-terminus and receptor loops.)
#     2. Download the charmm-gui.tgz and extract it into:
#        simulation/data/charmmgui/   (so that
#        simulation/data/charmmgui/gromacs/step5_assembly.gro exists)
#     3. Run this script.
#
#  B) packmol-memgen (AMBER route) ---------------------------------------
#     packmol-memgen --pdb simulation/data/8TH3_complex.pdb \
#                    --lipids POPC --saltcon 0.15 --outdir $WORK/8TH3/pmmg
#     Its output is AMBER (ff14SB + lipid17); convert with ParmEd to GROMACS
#     or run with pmemd.  Only use if route A is unavailable.
#
# This script copies the CHARMM-GUI GROMACS directory into $WORK/8TH3/prod
# so the production run (06) can run there without touching the download.
#
# Run:  bash simulation/05_prepare_membrane.sh
# ---------------------------------------------------------------------------
source "$(dirname "$0")/config.sh"
require gmx

GUI_ROOT="${CHARMMGUI_DIR:-$DATA/charmmgui}"
SRC="$(find "$GUI_ROOT" -maxdepth 4 -name 'step5_assembly.gro' 2>/dev/null | head -1)"

if [ -z "$SRC" ]; then
  cat <<EOF
ERROR: no CHARMM-GUI output found under $GUI_ROOT.
Route A:  upload simulation/data/8TH3_complex.pdb to
          https://charmm-gui.org/?doc=input/membrane
          then extract charmm-gui.tgz into $GUI_ROOT.
Route B:  run packmol-memgen (AMBER output) -- see header of this script.
EOF
  exit 1
fi

GUI_DIR="$(cd "$(dirname "$SRC")/.." && pwd)"
P="$WORK/8TH3/prod"
mkdir -p "$P"
cp -f "$GUI_DIR"/step5_assembly.gro "$P/" 2>/dev/null
cp -f "$GUI_DIR"/step5_assembly.top "$P/" 2>/dev/null || true
[ -d "$GUI_DIR/toppar" ] && cp -rf "$GUI_DIR/toppar" "$P/toppar"
[ -f "$GUI_DIR/index.ndx" ] && cp -f "$GUI_DIR/index.ndx" "$P/index.ndx"
# copy every itp (incl. posre) referenced by the topology
cp -f "$GUI_DIR"/*.itp "$P/" 2>/dev/null || true

log "CHARMM-GUI system staged:"
ls -la "$P" | sed 1d
log "Equilibration (.mdp steps 6.0-6.6) ships inside the CHARMM-GUI tarball;"
log "run it, then 06_run_membrane.sh for production."
log "Tip: CHARMM-GUI index.ndx defines the tc-grps used by our membrane mdps"